-- 11_sincronizar_reglas_base.sql
-- Lleva R01-R68 de produccion a los valores de sql/02_conocimiento.sql (pesos
-- 0,8 + 0,1 x gravedad y textos corregidos). Produccion se cargo con una version
-- anterior de 02 (todos los pesos en 1,0). Solo toca reglas no editadas desde la
-- aplicacion (version = 1). Idempotente.

